from getpass import getpass  # Запрашиваем пароль в терминале без отображения введённых символов.
from django.core.management.base import BaseCommand  # Базовый класс создаёт команду python manage.py seed.
from django.db import transaction  # Транзакция не позволит записать только половину начальных данных.
from portal.models import Course, User  # Импортируем справочник курсов и нашу модель пользователя.
class Command(BaseCommand):  # Django обнаруживает команду по классу с точным именем Command.
    help = "Создать три курса и экзаменационного администратора без удаления данных."  # Текст появляется в manage.py help seed.
    @transaction.atomic  # Все изменения команды выполняются целиком либо откатываются при ошибке.
    def handle(self, *args, **options):  # Стандартная точка входа собственной команды Django.
        titles = ["Основы алгоритмизации и программирования", "Основы веб-дизайна", "Основы проектирования баз данных"]  # Три названия точно соответствуют приложенной инструкции.
        for title in titles:  # По очереди обрабатываем каждое название курса.
            Course.objects.get_or_create(title=title)  # Повторный seed не дублирует существующий курс и не меняет его доступность.
        admin, created = User.objects.get_or_create(username="Admin", defaults={"full_name": "Администратор", "phone": "8(900)000-00-00", "email": "admin@korochki.local", "is_staff": True})  # Пятибуквенный Admin — специальное исключение задания; при входе минимум шесть символов не проверяем.
        if created:  # Пароль и роль задаём только новому администратору, не сбрасывая существующий аккаунт при повторном запуске.
            password = getpass("Введите пароль администратора из вашего задания (ввод скрыт): ")  # Пароль задаёт пользователь; в публичном коде его нет.
            if len(password) < 8:  # Проверяем минимальную длину до сохранения аккаунта.
                raise RuntimeError("Пароль должен содержать не менее 8 символов. Повторите seed.")  # Исключение откатывает созданного в транзакции пользователя.
            admin.set_password(password)  # Храним PBKDF2-хеш со случайной солью; исходный пароль остаётся только в памяти.
            admin.save()  # Сохраняем полученный хеш в таблице пользователя.
        elif not admin.is_staff:  # Не повышаем права существующему обычному пользователю без явного решения владельца БД.
            raise RuntimeError("Логин Admin уже занят пользователем без роли администратора. Проверьте БД.")  # Ошибка откатит транзакцию вместо незаметного повышения привилегий.
        self.stdout.write(self.style.SUCCESS("Готово: три курса, администратор Admin. Существующий пароль не изменён."))  # Не выводим введённый пароль; повторный seed сохраняет существующие настройки.
